Definition free_common_mid (sp ra s0 s1 s2 s3 s4 s5 s6 : word) (m m' : mem) (W : list ivl) (lo U size b1 actx TH : Z) (T : list Z) (d : depot)
    (jk : list byte) (rest : list word) : Prop :=
     munch W m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
  /\ stk bsegs m' lo (bv_unsigned sp + -2208)
  /\ rw_cells bsegs m' (bv_unsigned sp + -2208) (put_frame sp s6 U TH)
  /\ rw_cells bsegs m' (bv_unsigned sp + -2128) [C8 (wz (bv_unsigned sp + -2128 + 16)); C8 (wz (Z.of_nat (length T)))]
  /\ u64arr bsegs m' (bv_unsigned sp + -2128 + 16) (map wz T ++ rest) /\ length rest = (255 - length T)%nat
  /\ rw_cells bsegs m' (bv_unsigned sp + -72) [C8 sp]
  /\ rw_cells bsegs m' (bv_unsigned sp + -64) [CB 8 jk; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra]
  /\ rw_cells bsegs m' (U + -16) [C1 (b8 3); C1 (b8 b1); C2 (wz 0); C4 (wz size); C8 (wz actx)]
  /\ rw_cells bsegs m' U [C8 (wz (d_putid d (depot_hash T)))]
  /\ stk bsegs m' (TH + 2800) (TH + 3168)
  /\ rw_cells bsegs m' (TH + 3168) [C1 (b8 0)]
  /\ rw_cells bsegs m' AIAINIT [C1 (b8 1); C1 (b8 0); C2 (wz 0)] /\ ia_after m'
  /\ DEPOT bsegs (d_put d (depot_hash T) (Z.of_nat (length T))) m'
  /\ u8arr bsegs m' (sh U) (repeat (b8 kAsanHeapFreeMagic) (Z.to_nat (nsh size)))
  /\ Forall (fun x => 0 <= x < 2^64) T /\ (1 <= length T <= 30)%nat.

Definition free_mid_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (m : mem) (W : list ivl) (lo U size b1 actx TH qcache : Z) (T : list Z) (d : depot) (ARM : mem -> Prop) : machine_state -> Prop :=
  fun ms' => exists (t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word) (jk : list byte) (rest : list word) m',
    ms' = MS (enq_regs sp gp tp s7 s8 s9 s10 s11 U size TH qcache t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6) F (Z_to_bv 64 0x54624) fc None m' (seg_rom bsegs)
    /\ free_common_mid sp ra s0 s1 s2 s3 s4 s5 s6 m m' W lo U size b1 actx TH T d jk rest
    /\ ARM m'.

